create table if not exists pets (id uuid primary key default gen_random_uuid(), owner_id uuid not null, name text not null, species text not null, age_years numeric, created_at timestamptz not null default now());
create table if not exists recordings (id uuid primary key default gen_random_uuid(), pet_id uuid not null references pets(id) on delete cascade, storage_path text, duration_ms integer, mime_type text, created_at timestamptz not null default now());
create table if not exists interpretations (id uuid primary key default gen_random_uuid(), recording_id uuid not null references recordings(id) on delete cascade, species text, vocalization_type text, likely_intent text not null, emotional_state text not null, confidence numeric not null check(confidence >= 0 and confidence <= 1), alternatives jsonb not null default '[]', signals jsonb not null default '[]', context_used jsonb not null default '[]', safety_flag boolean not null default false, model_version text not null, language text not null default 'en', created_at timestamptz not null default now());
create table if not exists feedback (id uuid primary key default gen_random_uuid(), interpretation_id uuid not null references interpretations(id) on delete cascade, label text not null, note text, created_at timestamptz not null default now());
create table if not exists pet_patterns (id uuid primary key default gen_random_uuid(), pet_id uuid not null references pets(id) on delete cascade, pattern text not null, evidence_count integer not null default 1, validated boolean not null default false, updated_at timestamptz not null default now());
create table if not exists model_versions (id uuid primary key default gen_random_uuid(), version text unique not null, notes text, created_at timestamptz not null default now());
create table if not exists ai_evaluations (id uuid primary key default gen_random_uuid(), interpretation_id uuid not null references interpretations(id) on delete cascade, expected_label text, predicted_label text, confidence numeric, feedback_label text, created_at timestamptz not null default now());
